1	use std::sync::Arc;
2	use std::sync::atomic::{AtomicU64, Ordering};
3	
4	use serde_json::Value;
5	use tokio::time::{Duration, Instant, sleep_until};
6	use tracing::warn;
7	use vllm_chat::ChatLlm;
8	use vllm_engine_core_client::EngineCoreClient;
9	use vllm_engine_core_client::protocol::lora::LoraRequest;
10	
11	use crate::lora::{LoadLoraError, LoraManager, LoraModelResolution, UnloadLoraError};
12	
13	use crate::server_info::{ServerInfoConfigFormat, ServerInfoSnapshot};
14	
15	const SHUTDOWN_REFCOUNT_POLL_INTERVAL: Duration = Duration::from_millis(100);
16	
17	/// Shared router state for the minimal single-model OpenAI server.
18	pub struct AppState {
19	    /// All public model IDs served by this frontend. The first entry is the
20	    /// primary ID used in responses; all entries are valid in requests.
21	    served_model_names: Vec<String>,
22	    /// Shared chat facade used by all requests.
23	    pub chat: ChatLlm,
24	    /// Whether to log a summary line for each completed request.
25	    pub enable_log_requests: bool,
26	    /// Whether to set X-Request-Id on every HTTP response.
27	    pub enable_request_id_headers: bool,
28	    /// Runtime server information returned by `/server_info`, when available.
29	    server_info: Option<ServerInfoSnapshot>,
30	    /// Number of in-flight inference requests currently owned by this frontend.
31	    server_load: AtomicU64,
32	    /// Dynamic LoRA adapter registry.
33	    lora_manager: LoraManager,
34	}
35	
36	impl AppState {
37	    /// Construct one application state instance.
38	    ///
39	    /// `served_model_names` must be non-empty; the first entry is the primary
40	    /// model ID returned in API responses.
41	    ///
42	    /// # Panics
43	    ///
44	    /// Panics if `served_model_names` is empty.
45	    pub fn new(served_model_names: Vec<String>, chat: ChatLlm) -> Self {
46	        assert!(
47	            !served_model_names.is_empty(),
48	            "served_model_names must not be empty"
49	        );
50	        Self {
51	            served_model_names,
52	            chat,
53	            enable_log_requests: false,
54	            enable_request_id_headers: false,
55	            server_info: None,
56	            server_load: AtomicU64::new(0),
57	            lora_manager: LoraManager::new(),
58	        }
59	    }
60	
61	    /// Enable per-request completion logging.
62	    pub fn with_log_requests(mut self, enabled: bool) -> Self {
63	        self.enable_log_requests = enabled;
64	        self
65	    }
66	
67	    /// Enable X-Request-Id response headers.
68	    pub fn with_request_id_headers(mut self, enabled: bool) -> Self {
69	        self.enable_request_id_headers = enabled;
70	        self
71	    }
72	
73	    /// Attach the runtime server information snapshot used by `/server_info`.
74	    pub(crate) fn with_server_info(mut self, server_info: ServerInfoSnapshot) -> Self {
75	        self.server_info = Some(server_info);
76	        self
77	    }
78	
79	    /// Build a `/server_info` response payload.
80	    pub(crate) fn server_info_response(
81	        &self,
82	        config_format: ServerInfoConfigFormat,
83	    ) -> Option<Value> {
84	        self.server_info.as_ref().map(|server_info| server_info.response(config_format))
85	    }
86	
87	    /// The primary model name echoed back in API responses (the first served
88	    /// name).
89	    pub fn primary_model_name(&self) -> &str {
90	        self.served_model_names.first().map(String::as_str).unwrap_or_default()
91	    }
92	
93	    /// All model names served by this frontend.
94	    pub fn served_model_names(&self) -> &[String] {
95	        &self.served_model_names
96	    }
97	
98	    /// Return base served model names plus dynamically loaded LoRA adapter
99	    /// names.
100	    pub async fn served_model_names_with_loras(&self) -> Vec<String> {
101	        self.lora_manager.served_model_names(&self.served_model_names).await
102	    }
103	
104	    /// Resolve the requested model against one dynamic LoRA registry snapshot.
105	    pub async fn resolve_model_with_loras(&self, model_name: Option<&str>) -> LoraModelResolution {
106	        self.lora_manager.resolve_model(&self.served_model_names, model_name).await
107	    }
108	
109	    /// Load one dynamic LoRA adapter and register it as a public model name.
110	    pub async fn load_lora(
111	        &self,
112	        lora_name: String,
113	        lora_path: String,
114	        load_inplace: bool,
115	        is_3d_lora_weight: bool,
116	    ) -> Result<LoraRequest, LoadLoraError> {
117	        self.lora_manager
118	            .load_lora(
119	                self.engine_core_client(),
120	                &self.served_model_names,
121	                lora_name,
122	                lora_path,
123	                load_inplace,
124	                is_3d_lora_weight,
125	            )
126	            .await
127	    }
128	
129	    /// Remove one dynamic LoRA adapter from the engine and public model
130	    /// registry.
131	    pub async fn unload_lora(
132	        &self,
133	        lora_name: &str,
134	        lora_int_id: Option<u64>,
135	    ) -> Result<LoraRequest, UnloadLoraError> {
136	        self.lora_manager
137	            .unload_lora(self.engine_core_client(), lora_name, lora_int_id)
138	            .await
139	    }
140	
141	    /// Return a reference to the underlying engine core client for utility
142	    /// calls.
143	    pub(crate) fn engine_core_client(&self) -> &EngineCoreClient {
144	        self.chat.engine_core_client()
145	    }
146	
147	    /// Return the current in-flight inference request count for the `/load`
148	    /// endpoint.
149	    pub fn server_load(&self) -> u64 {
150	        self.server_load.load(Ordering::Relaxed)
151	    }
152	
153	    /// Increment the in-flight inference request count, called by the load
154	    /// tracking middleware.
155	    pub(crate) fn increment_server_load(&self) {
156	        self.server_load.fetch_add(1, Ordering::Relaxed);
157	    }
158	
159	    /// Decrement the in-flight inference request count, called by the load
160	    /// tracking middleware.
161	    pub(crate) fn decrement_server_load(&self) {
162	        self.server_load.fetch_sub(1, Ordering::Relaxed);
163	    }
164	
165	    /// Wait until all request-owned references are dropped, then shut down the
166	    /// engine client.
167	    ///
168	    /// If the deadline elapses while request/connection tasks still hold state
169	    /// references, skip the clean engine-client shutdown and let process
170	    /// teardown reclaim the remaining resources.
171	    pub async fn shutdown(mut self: Arc<Self>, deadline: Instant) -> anyhow::Result<()> {
172	        loop {
173	            match Arc::try_unwrap(self) {
174	                Ok(state) => {
175	                    state.chat.shutdown().await?;
176	                    return Ok(());
177	                }
178	                Err(state) => self = state,
179	            }
180	            let ref_count = Arc::strong_count(&self);
181	
182	            let now = Instant::now();
183	            if now >= deadline {
184	                warn!(
185	                    ref_count,
186	                    "shutdown deadline elapsed before app state became idle; skipping engine-client shutdown"
187	                );
188	                return Ok(());
189	            }
190	
191	            sleep_until(std::cmp::min(
192	                deadline,
193	                now + SHUTDOWN_REFCOUNT_POLL_INTERVAL,
194	            ))
195	            .await;
196	        }
197	    }
198	}
