13	/// Endpoints that will be tracked for server load.
14	///
15	/// Derived from the Python frontend's actual `@load_aware_call` coverage. This
16	/// includes alias paths that delegate into decorated handlers, such as
17	/// `/v1/rerank` and `/v2/rerank`.
18	const TRACKED_HANDLERS: &[&str] = &[
19	    "/v1/responses",
20	    "/v1/responses/{response_id}",
21	    "/v1/responses/{response_id}/cancel",
22	    "/v1/messages",
23	    "/v1/messages/count_tokens",
24	    "/v1/chat/completions",
25	    "/v1/completions",
26	    "/v1/audio/transcriptions",
27	    "/v1/audio/translations",
28	    "/v1/embeddings",
29	    "/pooling",
30	    "/classify",
31	    "/score",
32	    "/v1/score",
33	    "/rerank",
34	    "/v1/rerank",
35	    "/v2/rerank",
36	    "/inference/v1/generate",
37	];
38	
39	/// Track frontend-local in-flight inference requests for the `/load` endpoint.
40	pub async fn track_server_load(
41	    State(state): State<Arc<AppState>>,
42	    req: Request,
43	    next: Next,
44	) -> Response {
45	    let handler = req
46	        .extensions()
47	        .get::<MatchedPath>()
48	        .map_or_else(|| "none", |path| path.as_str());
49	
50	    if !TRACKED_HANDLERS.contains(&handler) {
51	        return next.run(req).await;
52	    }
53	
54	    state.increment_server_load();
55	    let guard = ServerLoadGuard {
56	        state: Arc::downgrade(&state),
57	    };
58	    let response = next.run(req).await;
59	
60	    let (parts, body) = response.into_parts();
61	    Response::from_parts(
62	        parts,
63	        Body::new(LoadTrackedBody {
64	            inner: body,
65	            _guard: guard,
66	        }),
67	    )
68	}
69	
70	/// A guard that decrements the server load when dropped.
71	struct ServerLoadGuard {
72	    state: Weak<AppState>,
73	}
74	
75	impl Drop for ServerLoadGuard {
76	    fn drop(&mut self) {
77	        if let Some(state) = self.state.upgrade() {
78	            state.decrement_server_load();
79	        }
80	    }
81	}
82	
83	/// A wrapper around response bodies that tracks server load by holding a
84	/// `ServerLoadGuard`, which will decrement the load when the body is fully
85	/// consumed and dropped.
86	struct LoadTrackedBody {
87	    inner: Body,
88	    _guard: ServerLoadGuard,
89	}
90	
91	// Simply delegate all `HttpBody` methods to the inner body.
92	impl HttpBody for LoadTrackedBody {
93	    type Data = Bytes;
94	    type Error = axum::Error;
95	
96	    fn poll_frame(
97	        mut self: Pin<&mut Self>,
98	        cx: &mut Context<'_>,
99	    ) -> Poll<Option<Result<Frame<Self::Data>, Self::Error>>> {
100	        Pin::new(&mut self.inner).poll_frame(cx)
101	    }
102	
103	    fn is_end_stream(&self) -> bool {
104	        self.inner.is_end_stream()
105	    }
106	
107	    fn size_hint(&self) -> SizeHint {
108	        self.inner.size_hint()
109	    }
110	}
