/// receive `401 Unauthorized` with a `{"error": "Unauthorized"}` JSON body.
pub async fn require_api_key(
    State(state): State<Arc<AppState>>,
    req: Request,
    next: Next,
) -> Response {
    // Allow CORS preflight and any route that is not behind a guarded prefix.
    if req.method() == Method::OPTIONS || !is_guarded(req.uri().path()) {
        return next.run(req).await;
    }

    if request_is_authorized(&state, &req) {
        next.run(req).await
    } else {
        unauthorized()
    }
}

/// Whether `path` falls under one of the guarded route prefixes.
fn is_guarded(path: &str) -> bool {
    GUARDED_PREFIXES.iter().any(|prefix| path.starts_with(prefix))
}

/// Whether the request carries a bearer token matching a configured API key.
fn request_is_authorized(state: &AppState, req: &Request) -> bool {
    req.headers()
        .get(header::AUTHORIZATION)
        .and_then(|value| value.to_str().ok())
        .and_then(|value| value.strip_prefix("Bearer "))
        .is_some_and(|token| state.is_valid_api_key(token))
}

/// Build the `401 Unauthorized` JSON response for rejected requests.
fn unauthorized() -> Response {
    (StatusCode::UNAUTHORIZED, Json(json!({ "error": "Unauthorized" }))).into_response()
}
